globalThis.EluceniaToolLocales={"id":"criterios-de-duke","clinicalApproval":"not-performed","professionalLanguageApproval":"not-performed","locales":{"pt-BR":{"tool":{"id":"criterios-de-duke","title":"Critérios de Duke-ISCVID 2023","summary":"Diagnóstico de endocardite infecciosa","lead":"Classifica a suspeita de endocardite infecciosa em definida, possível ou rejeitada, combinando critérios patológicos, maiores e menores.","fields":[["pato","<strong>Critério patológico:</strong> microrganismo em vegetação, tecido cardíaco, prótese ou êmbolo (cultura, histologia ou PCR), ou endocardite ativa na histologia","chk",{}],["maior_micro","<strong>Maior microbiológico:</strong> agente típico em ≥ 2 hemoculturas separadas, agente ocasional em ≥ 3, PCR positiva no sangue para <em>Coxiella</em>, <em>Bartonella</em> ou <em>T. whipplei</em>, ou sorologia específica (IgG anti-fase I de <em>C. burnetii</em> &gt; 1:800; IgG para <em>Bartonella</em> ≥ 1:800)","chk",{}],["maior_img","<strong>Maior de imagem:</strong> vegetação, perfuração, aneurisma, abscesso, pseudoaneurisma ou fístula ao eco/TC cardíaca; regurgitação valvar nova significativa; deiscência nova de prótese; ou PET/CT com FDG alterado em valva ou eletrodo","chk",{}],["maior_cir","<strong>Maior cirúrgico:</strong> endocardite documentada por inspeção direta na cirurgia cardíaca, apenas na ausência de critério maior de imagem e de confirmação histológica ou microbiológica posterior","chk",{}],["men_pred","<strong>Menor:</strong> predisposição (endocardite prévia, prótese valvar, reparo valvar, cardiopatia congênita, regurgitação ou estenose valvar, dispositivo intracardíaco, cardiomiopatia hipertrófica, uso de drogas injetáveis)","chk",{}],["men_febre","<strong>Menor:</strong> febre &gt; 38,0 °C","chk",{}],["men_vasc","<strong>Menor:</strong> fenômenos vasculares (embolia arterial, infarto séptico pulmonar, abscesso cerebral ou esplênico, aneurisma micótico, hemorragia intracraniana, hemorragia conjuntival, lesões de Janeway, púrpura purulenta)","chk",{}],["men_imuno","<strong>Menor:</strong> fenômenos imunológicos (fator reumatoide positivo, nódulos de Osler, manchas de Roth, glomerulonefrite por imunocomplexos)","chk",{}],["men_micro","<strong>Menor:</strong> evidência microbiológica que não preenche o critério maior","chk",{}],["men_img","<strong>Menor:</strong> PET/CT com FDG alterado até 3 meses após implante de prótese, enxerto ou dispositivo","chk",{}],["men_exame","<strong>Menor:</strong> sopro de regurgitação novo ao exame físico, se o ecocardiograma não estiver disponível","chk",{}],["rej_alt","<strong>Rejeição:</strong> diagnóstico alternativo firme que explica o quadro","chk",{}],["rej_res","<strong>Rejeição:</strong> sem recorrência após antibioticoterapia por menos de 4 dias","chk",{}],["rej_pato","<strong>Rejeição:</strong> sem evidência patológica na cirurgia ou necrópsia, com antibioticoterapia por menos de 4 dias","chk",{}]],"formula":"<ul><li><strong>Definida:</strong> critério patológico, <em>ou</em> 2 maiores, <em>ou</em> 1 maior + 3 menores, <em>ou</em> 5 menores.</li><li><strong>Possível:</strong> 1 maior + 1 menor, <em>ou</em> 3 menores.</li><li><strong>Rejeitada:</strong> diagnóstico alternativo firme, resolução sem recorrência com menos de 4 dias de antibiótico, ausência de evidência patológica na cirurgia/necrópsia com menos de 4 dias de antibiótico, <em>ou</em> não preenche os critérios de possível.</li></ul><p><strong>Contagem do maior cirúrgico:</strong> só acrescenta um critério maior quando está selecionado e não há maior de imagem nem critério patológico selecionado. A confirmação posterior prevista na Tabela 2 deve ser verificada; o maior microbiológico do sangue não é automaticamente confirmação posterior em tecido.</p>","sources":[["Fowler VG et al. The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis: Updating the Modified Duke Criteria. Clin Infect Dis, 2023.","https://doi.org/10.1093/cid/ciad271"],["Li JS et al. Proposed modifications to the Duke criteria for the diagnosis of infective endocarditis. Clin Infect Dis, 2000.","https://doi.org/10.1086/313753"]],"methodVersion":"Duke-ISCVID 2023: combinações selecionadas da Tabela 1; maior cirúrgico condicionado pela Tabela 2, I.C, à ausência de maior de imagem e de confirmação posterior; sem equivalência automática com Duke 2000","limits":"Os critérios Duke-ISCVID 2023 dependem de definições específicas de microbiologia, imagem, inspeção intraoperatória e condições predisponentes. Alguns microrganismos só são classificados como típicos na presença de prótese intracardíaca. A edição 2023 também altera exigências de culturas da edição anterior; contagens isoladas sem essas definições não reproduzem o sistema completo. A Tabela 2, seção I.C, limita o maior cirúrgico à ausência de maior de imagem e de confirmação histológica ou microbiológica posterior. Nesta interface, selecionar o critério patológico impede a soma adicional do maior cirúrgico; o maior microbiológico do sangue permanece separado. A pessoa que preenche deve verificar a confirmação posterior e as definições da fonte: os campos booleanos não registram toda a cronologia ou a aquisição dos achados. A conferência corrige somente esta contagem e suas combinações selecionadas; não valida diagnóstico, desempenho clínico, tratamento ou o método completo.","limitsLocale":"pt-BR","resultLabels":{"Critérios de Duke-ISCVID 2023":"Critérios de Duke-ISCVID 2023"},"resultUnits":{},"resultValues":{}},"shared":{"select":"Selecione","yes":"Sim","no":"Não","optional":"opcional","numeric":"Valor numérico","range":"intervalo","calculate":"Calcular","calculating":"Calculando…","clear":"Limpar","heading":"Calcular com transparência","intro":"Confira população, unidades e versão. O resultado apresenta a fórmula ou classificação, sem decisão terapêutica automática.","restricted":"Ficha disponível para consulta","restrictedNote":"Cálculo suspenso nesta edição. O inventário, a pendência e as fontes permanecem públicos.","resultNote":"Resultado da fórmula ou classificação. Interpretação, conduta e aplicabilidade dependem da avaliação profissional e da fonte selecionada.","invalid":"Não foi possível calcular com esses valores. Confira as condições de uso.","unavailable":"O serviço de cálculo está indisponível. Tente novamente.","connection":"Não foi possível consultar o serviço de cálculo. Verifique a conexão e tente novamente.","check":"Confira os valores informados.","fleischner":"Antes de calcular: referência para nódulos pulmonares incidentais. As recomendações não se aplicam a pessoas com menos de 35 anos, rastreamento de câncer de pulmão, imunossupressão ou câncer primário conhecido.","incompleteAssessment":"Sem avaliação completa, não é possível calcular a pontuação total."},"ui":{"brand":"ELUCENIA · código de integração","clinical":"Revisão clínica independente não realizada.","conditions":"condições, fontes e permissões","record":"Ficha e referências","code":"Código JavaScript","cases":"Casos de referência","language":"Idioma","formula":"Fórmula documentada","edition":"Edição do método","limits":"Limites e população","references":"Referências"}},"en":{"tool":{"id":"criterios-de-duke","title":"2023 Duke–ISCVID criteria","titleLocale":"en","summary":"Infective endocarditis diagnosis","lead":"Classifies suspected infective endocarditis as definite, possible or rejected by combining pathological, major and minor criteria.","fields":[["pato","<strong>Pathological criterion:</strong> microorganism in vegetation, cardiac tissue, prosthesis or embolus (culture, histology or PCR), or active endocarditis on histology","chk",{"unitLocale":"en","displayLocale":"en"}],["maior_micro","<strong>Major microbiological criterion:</strong> typical organism in ≥ 2 separate blood cultures, occasional organism in ≥ 3, blood PCR positive for <em>Coxiella</em>, <em>Bartonella</em> or <em>T. whipplei</em>, or specific serology (phase I IgG against <em>C. burnetii</em> &gt; 1:800; IgG against <em>Bartonella</em> ≥ 1:800)","chk",{"unitLocale":"en","displayLocale":"en"}],["maior_img","<strong>Major imaging criterion:</strong> vegetation, perforation, aneurysm, abscess, pseudoaneurysm or fistula on echocardiography/cardiac CT; significant new valvular regurgitation; new prosthetic dehiscence; or abnormal FDG uptake on PET/CT in a valve or lead","chk",{"unitLocale":"en","displayLocale":"en"}],["maior_cir","<strong>Surgical major criterion:</strong> endocarditis documented by direct inspection during cardiac surgery, only in the absence of a major imaging criterion and subsequent histologic or microbiologic confirmation","chk",{"unitLocale":"en","displayLocale":"en"}],["men_pred","<strong>Minor:</strong> predisposition (previous endocarditis, prosthetic valve, valve repair, congenital heart disease, valve regurgitation or stenosis, intracardiac device, hypertrophic cardiomyopathy, injection drug use)","chk",{"unitLocale":"en","displayLocale":"en"}],["men_febre","<strong>Minor:</strong> fever &gt; 38.0 °C","chk",{"unitLocale":"en","displayLocale":"en"}],["men_vasc","<strong>Minor:</strong> vascular phenomena (arterial embolism, septic pulmonary infarction, cerebral or splenic abscess, mycotic aneurysm, intracranial hemorrhage, conjunctival hemorrhage, Janeway lesions, purulent purpura)","chk",{"unitLocale":"en","displayLocale":"en"}],["men_imuno","<strong>Minor:</strong> immunological phenomena (positive rheumatoid factor, Osler nodes, Roth spots, immune-complex glomerulonephritis)","chk",{"unitLocale":"en","displayLocale":"en"}],["men_micro","<strong>Minor:</strong> microbiological evidence that does not meet a major criterion","chk",{"unitLocale":"en","displayLocale":"en"}],["men_img","<strong>Minor:</strong> abnormal FDG PET/CT within 3 months of prosthesis, graft or device implantation","chk",{"unitLocale":"en","displayLocale":"en"}],["men_exame","<strong>Minor:</strong> new regurgitant murmur on physical examination if echocardiography is unavailable","chk",{"unitLocale":"en","displayLocale":"en"}],["rej_alt","<strong>Rejected:</strong> a firm alternative diagnosis explains the presentation","chk",{"unitLocale":"en","displayLocale":"en"}],["rej_res","<strong>Rejected:</strong> no recurrence after fewer than 4 days of antibiotic therapy","chk",{"unitLocale":"en","displayLocale":"en"}],["rej_pato","<strong>Rejected:</strong> no pathological evidence at surgery or autopsy, with fewer than 4 days of antibiotic therapy","chk",{"unitLocale":"en","displayLocale":"en"}]],"formula":"<ul><li><strong>Definite:</strong> pathological criterion, <em>or</em> 2 major, <em>or</em> 1 major + 3 minor, <em>or</em> 5 minor.</li><li><strong>Possible:</strong> 1 major + 1 minor, <em>or</em> 3 minor.</li><li><strong>Rejected:</strong> firm alternative diagnosis, resolution without recurrence after less than 4 days of antibiotics, no pathological evidence at surgery/autopsy after less than 4 days of antibiotics, <em>or</em> does not meet possible criteria.</li></ul><p><strong>Surgical major count:</strong> adds one major criterion only when selected and neither a major imaging criterion nor the pathological criterion is selected. The subsequent confirmation described in Table 2 must be checked; a blood microbiological major criterion is not automatically subsequent tissue confirmation.</p>","sources":[["Fowler VG et al. The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis: Updating the Modified Duke Criteria. Clin Infect Dis, 2023.","https://doi.org/10.1093/cid/ciad271"],["Li JS et al. Proposed modifications to the Duke criteria for the diagnosis of infective endocarditis. Clin Infect Dis, 2000.","https://doi.org/10.1086/313753"]],"methodVersion":"Duke-ISCVID 2023: selected Table 1 combinations; the surgical major criterion is subject to Table 2, I.C, requiring the absence of a major imaging criterion and of subsequent confirmation; no automatic equivalence with Duke 2000","methodVersionLocale":"en","limits":"The Duke-ISCVID 2023 criteria depend on specific definitions for microbiology, imaging, intraoperative inspection and predisposing conditions. Some microorganisms are classified as typical only in the presence of an intracardiac prosthesis. The 2023 edition also changes culture requirements from the previous edition; counts alone without these definitions do not reproduce the complete system. Table 2, section I.C, restricts the surgical major criterion to the absence of a major imaging criterion and subsequent histologic or microbiologic confirmation. In this interface, selecting the pathological criterion prevents an additional surgical major count; the blood microbiological major criterion remains separate. The person completing the form must check subsequent confirmation and the source definitions: the Boolean fields do not record the entire chronology or how findings were established. This check corrects only this count and its selected combinations; it does not validate diagnosis, clinical performance, treatment or the complete method.","limitsLocale":"en","resultLabels":{"Duke-ISCVID 2023":"Duke-ISCVID 2023","Critérios de Duke-ISCVID 2023":"2023 Duke–ISCVID criteria"},"resultUnits":{},"resultValues":{"Definida":"Definite","Possível":"Possible","Rejeitada":"Rejected"}},"shared":{"select":"Select","yes":"Yes","no":"No","optional":"optional","numeric":"Numeric value","range":"range","calculate":"Calculate","calculating":"Calculating…","clear":"Clear","heading":"Calculate with transparency","intro":"Check the population, units and version. The result shows the formula or classification; it does not make an automatic treatment decision.","restricted":"Record available for reference","restrictedNote":"Calculation is suspended in this release. The inventory, outstanding review and sources remain public.","resultNote":"Formula or classification result. Interpretation, care and applicability depend on professional assessment and the selected source.","invalid":"Unable to calculate with these values. Check the conditions of use.","unavailable":"The calculation service is unavailable. Try again.","connection":"Unable to reach the calculation service. Check your connection and try again.","check":"Check the values entered.","fleischner":"Before calculating: reference for incidental pulmonary nodules. The recommendations do not apply to people under 35, lung cancer screening, immunosuppression or known primary cancer.","incompleteAssessment":"A total score cannot be calculated without a complete assessment."},"ui":{"brand":"ELUCENIA · integration code","clinical":"Independent clinical review has not been performed.","conditions":"conditions, sources and permissions","record":"Record and references","code":"JavaScript code","cases":"Reference cases","language":"Language","formula":"Documented formula","edition":"Method edition","limits":"Limits and population","references":"References"}},"es":{"tool":{"id":"criterios-de-duke","title":"Criterios Duke-ISCVID 2023","titleLocale":"es","summary":"Diagnóstico de endocarditis infecciosa","lead":"Clasifica sospecha de endocarditis definida, posible o rechazada combinando criterios patológicos, mayores y menores.","fields":[["pato","<strong>Criterio patológico:</strong> microorganismo en vegetación, tejido cardíaco, prótesis o émbolo (cultivo, histología o PCR), o endocarditis activa en la histología","chk",{"unitLocale":"es","displayLocale":"es"}],["maior_micro","<strong>Criterio mayor microbiológico:</strong> agente típico en ≥ 2 hemocultivos separados, agente ocasional en ≥ 3, PCR sanguínea positiva para <em>Coxiella</em>, <em>Bartonella</em> o <em>T. whipplei</em>, o serología específica (IgG de fase I contra <em>C. burnetii</em> &gt; 1:800; IgG contra <em>Bartonella</em> ≥ 1:800)","chk",{"unitLocale":"es","displayLocale":"es"}],["maior_img","<strong>Criterio mayor de imagen:</strong> vegetación, perforación, aneurisma, absceso, pseudoaneurisma o fístula en ecocardiografía/TC cardíaca; nueva regurgitación valvular significativa; nueva dehiscencia protésica; o captación anormal de FDG en PET/TC en válvula o electrodo","chk",{"unitLocale":"es","displayLocale":"es"}],["maior_cir","<strong>Criterio mayor quirúrgico:</strong> endocarditis documentada por inspección directa durante la cirugía cardíaca, únicamente en ausencia de un criterio mayor de imagen y de confirmación histológica o microbiológica posterior","chk",{"unitLocale":"es","displayLocale":"es"}],["men_pred","<strong>Menor:</strong> predisposición (endocarditis previa, prótesis valvular, reparación valvular, cardiopatía congénita, regurgitación o estenosis valvular, dispositivo intracardíaco, miocardiopatía hipertrófica, uso de drogas inyectables)","chk",{"unitLocale":"es","displayLocale":"es"}],["men_febre","<strong>Menor:</strong> fiebre &gt; 38,0 °C","chk",{"unitLocale":"es","displayLocale":"es"}],["men_vasc","<strong>Menor:</strong> fenómenos vasculares (embolia arterial, infarto pulmonar séptico, absceso cerebral o esplénico, aneurisma micótico, hemorragia intracraneal, hemorragia conjuntival, lesiones de Janeway, púrpura purulenta)","chk",{"unitLocale":"es","displayLocale":"es"}],["men_imuno","<strong>Menor:</strong> fenómenos inmunológicos (factor reumatoide positivo, nódulos de Osler, manchas de Roth, glomerulonefritis por inmunocomplejos)","chk",{"unitLocale":"es","displayLocale":"es"}],["men_micro","<strong>Menor:</strong> evidencia microbiológica que no cumple el criterio mayor","chk",{"unitLocale":"es","displayLocale":"es"}],["men_img","<strong>Menor:</strong> PET/TC con FDG anormal en los 3 meses posteriores a la implantación de prótesis, injerto o dispositivo","chk",{"unitLocale":"es","displayLocale":"es"}],["men_exame","<strong>Menor:</strong> nuevo soplo de regurgitación en la exploración física si no se dispone de ecocardiograma","chk",{"unitLocale":"es","displayLocale":"es"}],["rej_alt","<strong>Rechazo:</strong> un diagnóstico alternativo firme explica el cuadro","chk",{"unitLocale":"es","displayLocale":"es"}],["rej_res","<strong>Rechazo:</strong> sin recurrencia tras menos de 4 días de antibioterapia","chk",{"unitLocale":"es","displayLocale":"es"}],["rej_pato","<strong>Rechazo:</strong> sin evidencia anatomopatológica en cirugía o autopsia, con menos de 4 días de antibioterapia","chk",{"unitLocale":"es","displayLocale":"es"}]],"formula":"<ul><li><strong>Definida:</strong> criterio patológico, <em>o</em> 2 mayores, <em>o</em> 1 mayor + 3 menores, <em>o</em> 5 menores.</li><li><strong>Posible:</strong> 1 mayor + 1 menor, <em>o</em> 3 menores.</li><li><strong>Rechazada:</strong> diagnóstico alternativo firme, resolución sin recurrencia con menos de 4 días de antibióticos, sin evidencia patológica en cirugía/autopsia con menos de 4 días de antibióticos, <em>o</em> no cumple criterios de posible.</li></ul><p><strong>Recuento del criterio mayor quirúrgico:</strong> añade un criterio mayor solo cuando está seleccionado y no está seleccionado ningún criterio mayor de imagen ni el criterio patológico. Debe comprobarse la confirmación posterior prevista en la Tabla 2; el criterio mayor microbiológico de la sangre no equivale automáticamente a una confirmación posterior en tejido.</p>","sources":[["Fowler VG et al. The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis: Updating the Modified Duke Criteria. Clin Infect Dis, 2023.","https://doi.org/10.1093/cid/ciad271"],["Li JS et al. Proposed modifications to the Duke criteria for the diagnosis of infective endocarditis. Clin Infect Dis, 2000.","https://doi.org/10.1086/313753"]],"methodVersion":"Duke-ISCVID 2023: combinaciones seleccionadas de la Tabla 1; criterio mayor quirúrgico condicionado por la Tabla 2, I.C, a la ausencia de un criterio mayor de imagen y de confirmación posterior; sin equivalencia automática con Duke 2000","methodVersionLocale":"es","limits":"Los criterios Duke-ISCVID 2023 dependen de definiciones específicas de microbiología, imagen, inspección intraoperatoria y condiciones predisponentes. Algunos microorganismos solo se clasifican como típicos en presencia de una prótesis intracardíaca. La edición 2023 también modifica requisitos de cultivos de la edición anterior; los recuentos aislados sin estas definiciones no reproducen el sistema completo. La Tabla 2, sección I.C, limita el criterio mayor quirúrgico a la ausencia de un criterio mayor de imagen y de confirmación histológica o microbiológica posterior. En esta interfaz, seleccionar el criterio patológico impide sumar además el criterio mayor quirúrgico; el criterio mayor microbiológico de la sangre permanece separado. Quien rellena el formulario debe comprobar la confirmación posterior y las definiciones de la fuente: los campos booleanos no registran toda la cronología ni cómo se obtuvieron los hallazgos. La comprobación corrige solo este recuento y sus combinaciones seleccionadas; no valida el diagnóstico, el rendimiento clínico, el tratamiento ni el método completo.","limitsLocale":"es","resultLabels":{"Duke-ISCVID 2023":"Duke-ISCVID 2023","Critérios de Duke-ISCVID 2023":"Criterios Duke-ISCVID 2023"},"resultUnits":{},"resultValues":{"Definida":"Definida","Possível":"Posible","Rejeitada":"Rechazada"}},"shared":{"select":"Seleccione","yes":"Sí","no":"No","optional":"opcional","numeric":"Valor numérico","range":"intervalo","calculate":"Calcular","calculating":"Calculando…","clear":"Limpiar","heading":"Calcular con transparencia","intro":"Compruebe la población, las unidades y la versión. El resultado presenta la fórmula o clasificación, sin decisión terapéutica automática.","restricted":"Ficha disponible para consulta","restrictedNote":"Cálculo suspendido en esta edición. El inventario, la revisión pendiente y las fuentes siguen siendo públicos.","resultNote":"Resultado de la fórmula o clasificación. La interpretación, la conducta y la aplicabilidad dependen de la evaluación profesional y de la fuente seleccionada.","invalid":"No se puede calcular con estos valores. Compruebe las condiciones de uso.","unavailable":"El servicio de cálculo no está disponible. Inténtelo de nuevo.","connection":"No se pudo consultar el servicio de cálculo. Compruebe la conexión e inténtelo de nuevo.","check":"Compruebe los valores introducidos.","fleischner":"Antes de calcular: referencia para nódulos pulmonares incidentales. Las recomendaciones no se aplican a menores de 35 años, cribado de cáncer de pulmón, inmunosupresión o cáncer primario conocido.","incompleteAssessment":"No se puede calcular el total sin una evaluación completa."},"ui":{"brand":"ELUCENIA · código de integración","clinical":"No se ha realizado una revisión clínica independiente.","conditions":"condiciones, fuentes y permisos","record":"Ficha y referencias","code":"Código JavaScript","cases":"Casos de referencia","language":"Idioma","formula":"Fórmula documentada","edition":"Edición del método","limits":"Límites y población","references":"Referencias"}},"fr":{"tool":{"id":"criterios-de-duke","title":"Critères Duke-ISCVID 2023","titleLocale":"fr","summary":"Diagnostic d’endocardite infectieuse","lead":"Classe la suspicion d’endocardite certaine, possible ou exclue par combinaison de critères pathologiques, majeurs et mineurs.","fields":[["pato","<strong>Critère pathologique :</strong> microorganisme dans une végétation, un tissu cardiaque, une prothèse ou un embole (culture, histologie ou PCR), ou endocardite active en histologie","chk",{"unitLocale":"fr","displayLocale":"fr"}],["maior_micro","<strong>Critère majeur microbiologique :</strong> agent typique dans ≥ 2 hémocultures distinctes, agent occasionnel dans ≥ 3, PCR sanguine positive pour <em>Coxiella</em>, <em>Bartonella</em> ou <em>T. whipplei</em>, ou sérologie spécifique (IgG de phase I contre <em>C. burnetii</em> &gt; 1:800 ; IgG contre <em>Bartonella</em> ≥ 1:800)","chk",{"unitLocale":"fr","displayLocale":"fr"}],["maior_img","<strong>Critère majeur d’imagerie :</strong> végétation, perforation, anévrisme, abcès, pseudoanévrisme ou fistule à l’échographie/TDM cardiaque ; nouvelle régurgitation valvulaire significative ; nouvelle désinsertion de prothèse ; ou captation anormale de FDG à la TEP/TDM d’une valve ou d’une sonde","chk",{"unitLocale":"fr","displayLocale":"fr"}],["maior_cir","<strong>Critère majeur chirurgical :</strong> endocardite documentée par inspection directe pendant la chirurgie cardiaque, uniquement en l’absence de critère majeur d’imagerie et de confirmation histologique ou microbiologique ultérieure","chk",{"unitLocale":"fr","displayLocale":"fr"}],["men_pred","<strong>Mineur :</strong> prédisposition (endocardite antérieure, prothèse valvulaire, réparation valvulaire, cardiopathie congénitale, régurgitation ou sténose valvulaire, dispositif intracardiaque, cardiomyopathie hypertrophique, usage de drogues injectables)","chk",{"unitLocale":"fr","displayLocale":"fr"}],["men_febre","<strong>Mineur :</strong> fièvre &gt; 38,0 °C","chk",{"unitLocale":"fr","displayLocale":"fr"}],["men_vasc","<strong>Mineur :</strong> phénomènes vasculaires (embolie artérielle, infarctus pulmonaire septique, abcès cérébral ou splénique, anévrisme mycotique, hémorragie intracrânienne, hémorragie conjonctivale, lésions de Janeway, purpura purulent)","chk",{"unitLocale":"fr","displayLocale":"fr"}],["men_imuno","<strong>Mineur :</strong> phénomènes immunologiques (facteur rhumatoïde positif, nodules d’Osler, taches de Roth, glomérulonéphrite à complexes immuns)","chk",{"unitLocale":"fr","displayLocale":"fr"}],["men_micro","<strong>Mineur :</strong> preuve microbiologique ne remplissant pas un critère majeur","chk",{"unitLocale":"fr","displayLocale":"fr"}],["men_img","<strong>Mineur :</strong> TEP/TDM au FDG anormale dans les 3 mois suivant l’implantation d’une prothèse, d’un greffon ou d’un dispositif","chk",{"unitLocale":"fr","displayLocale":"fr"}],["men_exame","<strong>Mineur :</strong> nouveau souffle de régurgitation à l’examen clinique si l’échocardiographie n’est pas disponible","chk",{"unitLocale":"fr","displayLocale":"fr"}],["rej_alt","<strong>Rejet :</strong> un diagnostic alternatif certain explique le tableau","chk",{"unitLocale":"fr","displayLocale":"fr"}],["rej_res","<strong>Rejet :</strong> absence de récidive après moins de 4 jours d’antibiothérapie","chk",{"unitLocale":"fr","displayLocale":"fr"}],["rej_pato","<strong>Rejet :</strong> absence de preuve anatomopathologique à la chirurgie ou à l’autopsie, après moins de 4 jours d’antibiothérapie","chk",{"unitLocale":"fr","displayLocale":"fr"}]],"formula":"<ul><li><strong>Certaine :</strong> critère pathologique, <em>ou</em> 2 majeurs, <em>ou</em> 1 majeur + 3 mineurs, <em>ou</em> 5 mineurs.</li><li><strong>Possible :</strong> 1 majeur + 1 mineur, <em>ou</em> 3 mineurs.</li><li><strong>Exclue :</strong> diagnostic alternatif certain, résolution sans récidive après moins de 4 jours d’antibiotiques, absence de preuve pathologique en chirurgie/autopsie après moins de 4 jours d’antibiotiques, <em>ou</em> ne remplit pas les critères de possible.</li></ul><p><strong>Comptage du critère majeur chirurgical :</strong> ajoute un critère majeur uniquement s’il est sélectionné et si ni un critère majeur d’imagerie ni le critère pathologique ne sont sélectionnés. La confirmation ultérieure prévue dans le Tableau 2 doit être vérifiée ; un critère majeur microbiologique sanguin ne constitue pas automatiquement une confirmation ultérieure dans un tissu.</p>","sources":[["Fowler VG et al. The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis: Updating the Modified Duke Criteria. Clin Infect Dis, 2023.","https://doi.org/10.1093/cid/ciad271"],["Li JS et al. Proposed modifications to the Duke criteria for the diagnosis of infective endocarditis. Clin Infect Dis, 2000.","https://doi.org/10.1086/313753"]],"methodVersion":"Duke-ISCVID 2023 : combinaisons sélectionnées du Tableau 1 ; critère majeur chirurgical soumis à la condition du Tableau 2, I.C, d’absence de critère majeur d’imagerie et de confirmation ultérieure ; aucune équivalence automatique avec Duke 2000","methodVersionLocale":"fr","limits":"Les critères Duke-ISCVID 2023 dépendent de définitions précises de la microbiologie, de l’imagerie, de l’inspection peropératoire et des facteurs prédisposants. Certains microorganismes ne sont considérés comme typiques qu’en présence d’une prothèse intracardiaque. L’édition 2023 modifie aussi les exigences de cultures de l’édition précédente ; des comptes isolés sans ces définitions ne reproduisent pas le système complet. Le Tableau 2, section I.C, limite le critère majeur chirurgical à l’absence de critère majeur d’imagerie et de confirmation histologique ou microbiologique ultérieure. Dans cette interface, sélectionner le critère pathologique empêche d’ajouter le critère majeur chirurgical ; le critère majeur microbiologique sanguin reste distinct. La personne qui remplit le formulaire doit vérifier la confirmation ultérieure et les définitions de la source : les champs booléens ne consignent ni toute la chronologie ni la manière dont les observations ont été établies. Cette vérification corrige seulement ce comptage et ses combinaisons sélectionnées ; elle ne valide ni le diagnostic, ni les performances cliniques, ni le traitement, ni la méthode complète.","limitsLocale":"fr","resultLabels":{"Duke-ISCVID 2023":"Duke-ISCVID 2023","Critérios de Duke-ISCVID 2023":"Critères Duke-ISCVID 2023"},"resultUnits":{},"resultValues":{"Definida":"Certaine","Possível":"Possible","Rejeitada":"Rejetée"}},"shared":{"select":"Sélectionner","yes":"Oui","no":"Non","optional":"facultatif","numeric":"Valeur numérique","range":"intervalle","calculate":"Calculer","calculating":"Calcul en cours…","clear":"Effacer","heading":"Calculer en toute transparence","intro":"Vérifiez la population, les unités et la version. Le résultat présente la formule ou la classification, sans décision thérapeutique automatique.","restricted":"Fiche disponible à la consultation","restrictedNote":"Calcul suspendu dans cette version. L’inventaire, la révision en attente et les sources restent publics.","resultNote":"Résultat de la formule ou de la classification. L’interprétation, la conduite et l’applicabilité dépendent de l’évaluation professionnelle et de la source sélectionnée.","invalid":"Calcul impossible avec ces valeurs. Vérifiez les conditions d’utilisation.","unavailable":"Le service de calcul est indisponible. Réessayez.","connection":"Impossible de joindre le service de calcul. Vérifiez la connexion et réessayez.","check":"Vérifiez les valeurs saisies.","fleischner":"Avant le calcul : référence pour les nodules pulmonaires fortuits. Les recommandations ne s’appliquent pas aux personnes de moins de 35 ans, au dépistage du cancer du poumon, à l’immunosuppression ou à un cancer primitif connu.","incompleteAssessment":"Le total ne peut pas être calculé sans évaluation complète."},"ui":{"brand":"ELUCENIA · code d’intégration","clinical":"Aucune révision clinique indépendante n’a été effectuée.","conditions":"conditions, sources et autorisations","record":"Fiche et références","code":"Code JavaScript","cases":"Cas de référence","language":"Langue","formula":"Formule documentée","edition":"Édition de la méthode","limits":"Limites et population","references":"Références"}},"de":{"tool":{"id":"criterios-de-duke","title":"Duke-ISCVID-Kriterien 2023","titleLocale":"de","summary":"Diagnose der infektiösen Endokarditis","lead":"Klassifiziert Endokarditisverdacht als gesichert, möglich oder ausgeschlossen durch pathologische, Haupt- und Nebenkriterien.","fields":[["pato","<strong>Pathologisches Kriterium:</strong> Mikroorganismus in Vegetation, Herzgewebe, Prothese oder Embolus (Kultur, Histologie oder PCR), oder histologisch aktive Endokarditis","chk",{"unitLocale":"de","displayLocale":"de"}],["maior_micro","<strong>Mikrobiologisches Hauptkriterium:</strong> typischer Erreger in ≥ 2 getrennten Blutkulturen, gelegentlicher Erreger in ≥ 3, positive Blut-PCR für <em>Coxiella</em>, <em>Bartonella</em> oder <em>T. whipplei</em>, oder spezifische Serologie (Phase-I-IgG gegen <em>C. burnetii</em> &gt; 1:800; IgG gegen <em>Bartonella</em> ≥ 1:800)","chk",{"unitLocale":"de","displayLocale":"de"}],["maior_img","<strong>Bildgebendes Hauptkriterium:</strong> Vegetation, Perforation, Aneurysma, Abszess, Pseudoaneurysma oder Fistel in Echokardiografie/Herz-CT; neue signifikante Klappenregurgitation; neue Prothesendehiszenz; oder abnorme FDG-Aufnahme im PET/CT an Klappe oder Elektrode","chk",{"unitLocale":"de","displayLocale":"de"}],["maior_cir","<strong>Chirurgisches Hauptkriterium:</strong> durch direkte Inspektion während einer Herzoperation dokumentierte Endokarditis, nur ohne bildgebendes Hauptkriterium und ohne nachfolgende histologische oder mikrobiologische Bestätigung","chk",{"unitLocale":"de","displayLocale":"de"}],["men_pred","<strong>Nebenkriterium:</strong> Prädisposition (frühere Endokarditis, Klappenprothese, Klappenrekonstruktion, angeborener Herzfehler, Klappenregurgitation oder -stenose, intrakardiales Gerät, hypertrophe Kardiomyopathie, intravenöser Drogenkonsum)","chk",{"unitLocale":"de","displayLocale":"de"}],["men_febre","<strong>Nebenkriterium:</strong> Fieber &gt; 38,0 °C","chk",{"unitLocale":"de","displayLocale":"de"}],["men_vasc","<strong>Nebenkriterium:</strong> vaskuläre Phänomene (arterielle Embolie, septischer Lungeninfarkt, Hirn- oder Milzabszess, mykotisches Aneurysma, intrakranielle Blutung, Bindehautblutung, Janeway-Läsionen, eitrige Purpura)","chk",{"unitLocale":"de","displayLocale":"de"}],["men_imuno","<strong>Nebenkriterium:</strong> immunologische Phänomene (positiver Rheumafaktor, Osler-Knötchen, Roth-Flecken, Immunkomplex-Glomerulonephritis)","chk",{"unitLocale":"de","displayLocale":"de"}],["men_micro","<strong>Nebenkriterium:</strong> mikrobiologischer Nachweis, der kein Hauptkriterium erfüllt","chk",{"unitLocale":"de","displayLocale":"de"}],["men_img","<strong>Nebenkriterium:</strong> abnormes FDG-PET/CT innerhalb von 3 Monaten nach Implantation einer Prothese, eines Transplantats oder eines Geräts","chk",{"unitLocale":"de","displayLocale":"de"}],["men_exame","<strong>Nebenkriterium:</strong> neues Regurgitationsgeräusch bei körperlicher Untersuchung, wenn keine Echokardiografie verfügbar ist","chk",{"unitLocale":"de","displayLocale":"de"}],["rej_alt","<strong>Ausgeschlossen:</strong> eine gesicherte Alternativdiagnose erklärt das Krankheitsbild","chk",{"unitLocale":"de","displayLocale":"de"}],["rej_res","<strong>Ausgeschlossen:</strong> kein Rezidiv nach weniger als 4 Tagen Antibiotikatherapie","chk",{"unitLocale":"de","displayLocale":"de"}],["rej_pato","<strong>Ausgeschlossen:</strong> kein pathologischer Nachweis bei Operation oder Autopsie nach weniger als 4 Tagen Antibiotikatherapie","chk",{"unitLocale":"de","displayLocale":"de"}]],"formula":"<ul><li><strong>Gesichert:</strong> pathologisches Kriterium, <em>oder</em> 2 Hauptkriterien, <em>oder</em> 1 Haupt- + 3 Nebenkriterien, <em>oder</em> 5 Nebenkriterien.</li><li><strong>Möglich:</strong> 1 Haupt- + 1 Nebenkriterium, <em>oder</em> 3 Nebenkriterien.</li><li><strong>Ausgeschlossen:</strong> sichere Alternativdiagnose, Abklingen ohne Rezidiv nach weniger als 4 Tagen Antibiotika, keine pathologischen Belege bei Operation/Autopsie nach weniger als 4 Tagen Antibiotika, <em>oder</em> Kriterien für möglich nicht erfüllt.</li></ul><p><strong>Zählung des chirurgischen Hauptkriteriums:</strong> fügt nur dann ein Hauptkriterium hinzu, wenn es ausgewählt ist und weder ein bildgebendes Hauptkriterium noch das pathologische Kriterium ausgewählt ist. Die in Tabelle 2 vorgesehene nachfolgende Bestätigung muss geprüft werden; ein mikrobiologisches Hauptkriterium aus Blut ist nicht automatisch eine nachfolgende Bestätigung im Gewebe.</p>","sources":[["Fowler VG et al. The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis: Updating the Modified Duke Criteria. Clin Infect Dis, 2023.","https://doi.org/10.1093/cid/ciad271"],["Li JS et al. Proposed modifications to the Duke criteria for the diagnosis of infective endocarditis. Clin Infect Dis, 2000.","https://doi.org/10.1086/313753"]],"methodVersion":"Duke-ISCVID 2023: ausgewählte Kombinationen aus Tabelle 1; chirurgisches Hauptkriterium gemäß Tabelle 2, I.C, nur ohne bildgebendes Hauptkriterium und ohne nachfolgende Bestätigung; keine automatische Gleichwertigkeit mit Duke 2000","methodVersionLocale":"de","limits":"Die Duke-ISCVID-Kriterien 2023 hängen von spezifischen Definitionen zu Mikrobiologie, Bildgebung, intraoperativer Inspektion und prädisponierenden Bedingungen ab. Manche Mikroorganismen gelten nur bei intrakardialem Prothesenmaterial als typisch. Die Ausgabe 2023 ändert außerdem Kulturanforderungen der vorherigen Ausgabe; isolierte Zählungen ohne diese Definitionen bilden das vollständige System nicht ab. Tabelle 2, Abschnitt I.C, beschränkt das chirurgische Hauptkriterium auf Fälle ohne bildgebendes Hauptkriterium und ohne nachfolgende histologische oder mikrobiologische Bestätigung. In dieser Oberfläche verhindert die Auswahl des pathologischen Kriteriums, dass zusätzlich das chirurgische Hauptkriterium gezählt wird; das mikrobiologische Hauptkriterium aus Blut bleibt davon getrennt. Die ausfüllende Person muss die nachfolgende Bestätigung und die Quelldefinitionen prüfen: Die booleschen Felder erfassen weder den vollständigen zeitlichen Verlauf noch die Erhebung der Befunde. Die Prüfung korrigiert nur diese Zählung und ihre ausgewählten Kombinationen; sie validiert weder Diagnose, klinische Leistung, Behandlung noch die vollständige Methode.","limitsLocale":"de","resultLabels":{"Duke-ISCVID 2023":"Duke-ISCVID 2023","Critérios de Duke-ISCVID 2023":"Duke-ISCVID-Kriterien 2023"},"resultUnits":{},"resultValues":{"Definida":"Gesichert","Possível":"Möglich","Rejeitada":"Verworfen"}},"shared":{"select":"Auswählen","yes":"Ja","no":"Nein","optional":"optional","numeric":"Numerischer Wert","range":"Bereich","calculate":"Berechnen","calculating":"Berechnung läuft…","clear":"Löschen","heading":"Transparent berechnen","intro":"Prüfen Sie Population, Einheiten und Version. Das Ergebnis zeigt die Formel oder Klassifikation, ohne automatisch eine Therapieentscheidung zu treffen.","restricted":"Eintrag zur Einsicht verfügbar","restrictedNote":"Die Berechnung ist in dieser Version ausgesetzt. Inventar, ausstehende Prüfung und Quellen bleiben öffentlich.","resultNote":"Ergebnis der Formel oder Klassifikation. Interpretation, Vorgehen und Anwendbarkeit hängen von der fachlichen Beurteilung und der ausgewählten Quelle ab.","invalid":"Berechnung mit diesen Werten nicht möglich. Prüfen Sie die Nutzungsbedingungen.","unavailable":"Der Berechnungsdienst ist nicht verfügbar. Versuchen Sie es erneut.","connection":"Der Berechnungsdienst ist nicht erreichbar. Prüfen Sie die Verbindung und versuchen Sie es erneut.","check":"Prüfen Sie die eingegebenen Werte.","fleischner":"Vor der Berechnung: Referenz für zufällig entdeckte Lungenrundherde. Die Empfehlungen gelten nicht für Personen unter 35 Jahren, Lungenkrebs-Screening, Immunsuppression oder bekannten Primärkrebs.","incompleteAssessment":"Ohne vollständige Untersuchung lässt sich kein Gesamtscore berechnen."},"ui":{"brand":"ELUCENIA · Integrationscode","clinical":"Eine unabhängige klinische Prüfung wurde nicht durchgeführt.","conditions":"Bedingungen, Quellen und Berechtigungen","record":"Eintrag und Referenzen","code":"JavaScript-Code","cases":"Referenzfälle","language":"Sprache","formula":"Dokumentierte Formel","edition":"Fassung der Methode","limits":"Grenzen und Population","references":"Referenzen"}},"it":{"tool":{"id":"criterios-de-duke","title":"Criteri Duke-ISCVID 2023","titleLocale":"it","summary":"Diagnosi di endocardite infettiva","lead":"Classifica il sospetto di endocardite definita, possibile o esclusa combinando criteri patologici, maggiori e minori.","fields":[["pato","<strong>Criterio patologico:</strong> microrganismo in vegetazione, tessuto cardiaco, protesi o embolo (coltura, istologia o PCR), oppure endocardite attiva all’istologia","chk",{"unitLocale":"it","displayLocale":"it"}],["maior_micro","<strong>Criterio maggiore microbiologico:</strong> agente tipico in ≥ 2 emocolture separate, agente occasionale in ≥ 3, PCR ematica positiva per <em>Coxiella</em>, <em>Bartonella</em> o <em>T. whipplei</em>, o sierologia specifica (IgG di fase I contro <em>C. burnetii</em> &gt; 1:800; IgG contro <em>Bartonella</em> ≥ 1:800)","chk",{"unitLocale":"it","displayLocale":"it"}],["maior_img","<strong>Criterio maggiore di imaging:</strong> vegetazione, perforazione, aneurisma, ascesso, pseudoaneurisma o fistola all’ecocardiografia/TC cardiaca; nuova regurgitazione valvolare significativa; nuova deiscenza protesica; o captazione anomala di FDG alla PET/TC su valvola o elettrodo","chk",{"unitLocale":"it","displayLocale":"it"}],["maior_cir","<strong>Criterio maggiore chirurgico:</strong> endocardite documentata mediante ispezione diretta durante la chirurgia cardiaca, solo in assenza di un criterio maggiore di imaging e di successiva conferma istologica o microbiologica","chk",{"unitLocale":"it","displayLocale":"it"}],["men_pred","<strong>Minore:</strong> predisposizione (endocardite pregressa, protesi valvolare, riparazione valvolare, cardiopatia congenita, regurgitazione o stenosi valvolare, dispositivo intracardiaco, cardiomiopatia ipertrofica, uso di droghe iniettabili)","chk",{"unitLocale":"it","displayLocale":"it"}],["men_febre","<strong>Minore:</strong> febbre &gt; 38,0 °C","chk",{"unitLocale":"it","displayLocale":"it"}],["men_vasc","<strong>Minore:</strong> fenomeni vascolari (embolia arteriosa, infarto polmonare settico, ascesso cerebrale o splenico, aneurisma micotico, emorragia intracranica, emorragia congiuntivale, lesioni di Janeway, porpora purulenta)","chk",{"unitLocale":"it","displayLocale":"it"}],["men_imuno","<strong>Minore:</strong> fenomeni immunologici (fattore reumatoide positivo, noduli di Osler, macchie di Roth, glomerulonefrite da immunocomplessi)","chk",{"unitLocale":"it","displayLocale":"it"}],["men_micro","<strong>Minore:</strong> evidenza microbiologica che non soddisfa il criterio maggiore","chk",{"unitLocale":"it","displayLocale":"it"}],["men_img","<strong>Minore:</strong> PET/TC con FDG anomalo entro 3 mesi dall’impianto di protesi, innesto o dispositivo","chk",{"unitLocale":"it","displayLocale":"it"}],["men_exame","<strong>Minore:</strong> nuovo soffio da regurgitazione all’esame obiettivo se l’ecocardiogramma non è disponibile","chk",{"unitLocale":"it","displayLocale":"it"}],["rej_alt","<strong>Esclusione:</strong> una diagnosi alternativa certa spiega il quadro","chk",{"unitLocale":"it","displayLocale":"it"}],["rej_res","<strong>Esclusione:</strong> nessuna recidiva dopo meno di 4 giorni di terapia antibiotica","chk",{"unitLocale":"it","displayLocale":"it"}],["rej_pato","<strong>Esclusione:</strong> nessuna evidenza patologica all’intervento o all’autopsia, con meno di 4 giorni di terapia antibiotica","chk",{"unitLocale":"it","displayLocale":"it"}]],"formula":"<ul><li><strong>Definita:</strong> criterio patologico, <em>o</em> 2 maggiori, <em>o</em> 1 maggiore + 3 minori, <em>o</em> 5 minori.</li><li><strong>Possibile:</strong> 1 maggiore + 1 minore, <em>o</em> 3 minori.</li><li><strong>Esclusa:</strong> diagnosi alternativa certa, risoluzione senza recidiva con meno di 4 giorni di antibiotici, nessuna evidenza patologica a chirurgia/autopsia con meno di 4 giorni di antibiotici, <em>o</em> non soddisfa i criteri di possibile.</li></ul><p><strong>Conteggio del criterio maggiore chirurgico:</strong> aggiunge un criterio maggiore solo quando è selezionato e non sono selezionati né un criterio maggiore di imaging né il criterio patologico. Va verificata la conferma successiva prevista dalla Tabella 2; il criterio maggiore microbiologico del sangue non equivale automaticamente a una successiva conferma nel tessuto.</p>","sources":[["Fowler VG et al. The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis: Updating the Modified Duke Criteria. Clin Infect Dis, 2023.","https://doi.org/10.1093/cid/ciad271"],["Li JS et al. Proposed modifications to the Duke criteria for the diagnosis of infective endocarditis. Clin Infect Dis, 2000.","https://doi.org/10.1086/313753"]],"methodVersion":"Duke-ISCVID 2023: combinazioni selezionate della Tabella 1; criterio maggiore chirurgico subordinato dalla Tabella 2, I.C, all’assenza di criterio maggiore di imaging e di conferma successiva; nessuna equivalenza automatica con Duke 2000","methodVersionLocale":"it","limits":"I criteri Duke-ISCVID 2023 dipendono da definizioni specifiche di microbiologia, diagnostica per immagini, ispezione intraoperatoria e condizioni predisponenti. Alcuni microrganismi sono classificati come tipici solo in presenza di una protesi intracardiaca. L’edizione 2023 modifica anche i requisiti delle colture rispetto all’edizione precedente; i soli conteggi, senza queste definizioni, non riproducono il sistema completo. La Tabella 2, sezione I.C, limita il criterio maggiore chirurgico all’assenza di un criterio maggiore di imaging e di successiva conferma istologica o microbiologica. In questa interfaccia, selezionare il criterio patologico impedisce di conteggiare anche il criterio maggiore chirurgico; il criterio maggiore microbiologico del sangue resta separato. Chi compila deve verificare la conferma successiva e le definizioni della fonte: i campi booleani non registrano l’intera cronologia né come sono stati accertati i reperti. La verifica corregge solo questo conteggio e le combinazioni selezionate; non convalida la diagnosi, le prestazioni cliniche, il trattamento o il metodo completo.","limitsLocale":"it","resultLabels":{"Duke-ISCVID 2023":"Duke-ISCVID 2023","Critérios de Duke-ISCVID 2023":"Criteri Duke-ISCVID 2023"},"resultUnits":{},"resultValues":{"Definida":"Certa","Possível":"Possibile","Rejeitada":"Respinta"}},"shared":{"select":"Seleziona","yes":"Sì","no":"No","optional":"facoltativo","numeric":"Valore numerico","range":"intervallo","calculate":"Calcola","calculating":"Calcolo in corso…","clear":"Cancella","heading":"Calcolare con trasparenza","intro":"Verifica popolazione, unità e versione. Il risultato mostra la formula o la classificazione, senza una decisione terapeutica automatica.","restricted":"Scheda disponibile per consultazione","restrictedNote":"Calcolo sospeso in questa versione. Inventario, revisione in sospeso e fonti rimangono pubblici.","resultNote":"Risultato della formula o classificazione. Interpretazione, condotta e applicabilità dipendono dalla valutazione professionale e dalla fonte selezionata.","invalid":"Impossibile calcolare con questi valori. Verifica le condizioni d’uso.","unavailable":"Il servizio di calcolo non è disponibile. Riprova.","connection":"Impossibile contattare il servizio di calcolo. Verifica la connessione e riprova.","check":"Verifica i valori inseriti.","fleischner":"Prima del calcolo: riferimento per noduli polmonari incidentali. Le raccomandazioni non si applicano a persone di età inferiore a 35 anni, screening del cancro del polmone, immunosoppressione o tumore primario noto.","incompleteAssessment":"Il totale non può essere calcolato senza una valutazione completa."},"ui":{"brand":"ELUCENIA · codice di integrazione","clinical":"Non è stata effettuata una revisione clinica indipendente.","conditions":"condizioni, fonti e autorizzazioni","record":"Scheda e riferimenti","code":"Codice JavaScript","cases":"Casi di riferimento","language":"Lingua","formula":"Formula documentata","edition":"Edizione del metodo","limits":"Limiti e popolazione","references":"Riferimenti"}},"ar":{"tool":{"id":"criterios-de-duke","title":"معايير Duke-ISCVID 2023","titleLocale":"ar","summary":"تشخيص التهاب الشغاف العدوائي","lead":"يصنّف الاشتباه بالتهاب الشغاف إلى مؤكد أو محتمل أو مستبعد، بدمج المعايير المرضية والكبرى والصغرى.","fields":[["pato","<strong>معيار مرضي:</strong> كائن دقيق في نابتة أو نسيج قلبي أو مادة قلبية اصطناعية أو صمّة (بالزرع أو النسج أو PCR)، أو التهاب شغاف نشط نسيجيًا","chk",{"unitLocale":"ar","displayLocale":"ar"}],["maior_micro","<strong>معيار ميكروبيولوجي رئيسي:</strong> ممرض نموذجي في ≥ ٢ زروع دم منفصلة، أو ممرض عرضي في ≥ ٣، أو PCR دم إيجابية لـ<em>Coxiella</em> أو <em>Bartonella</em> أو <em>T. whipplei</em>، أو مصلية نوعية (IgG للطور I من <em>C. burnetii</em> > ١:٨٠٠؛ IgG لـ<em>Bartonella</em> ≥ ١:٨٠٠)","chk",{"unitLocale":"ar","displayLocale":"ar"}],["maior_img","<strong>معيار تصوير رئيسي:</strong> نابتة أو انثقاب أو أم دم أو خراج أو أم دم كاذبة أو ناسور في إيكو/CT القلب؛ قلس صمامي جديد مهم؛ تفزر جديد للطرف الاصطناعي؛ أو FDG PET/CT غير طبيعي بالصمام أو القطب","chk",{"unitLocale":"ar","displayLocale":"ar"}],["maior_cir","<strong>المعيار الرئيسي الجراحي:</strong> التهاب شغاف موثّق بالفحص المباشر أثناء جراحة القلب، فقط عند غياب معيار رئيسي بالتصوير وغياب تأكيد نسيجي أو ميكروبيولوجي لاحق","chk",{"unitLocale":"ar","displayLocale":"ar"}],["men_pred","<strong>معيار ثانوي:</strong> استعداد (التهاب شغاف سابق، صمام اصطناعي، إصلاح صمام، مرض قلبي خلقي، قلس أو تضيق صمامي، جهاز داخل القلب، اعتلال عضلة القلب الضخامي، تعاطي المخدرات حقنًا)","chk",{"unitLocale":"ar","displayLocale":"ar"}],["men_febre","<strong>معيار ثانوي:</strong> حمى > ٣٨٫٠ °C","chk",{"unitLocale":"ar","displayLocale":"ar"}],["men_vasc","<strong>معيار ثانوي:</strong> ظواهر وعائية (انصمام شرياني، احتشاء رئوي إنتاني، خراج دماغي أو طحالي، أم دم إنتانية، نزف داخل القحف أو الملتحمة، آفات Janeway، فرفرية قيحية)","chk",{"unitLocale":"ar","displayLocale":"ar"}],["men_imuno","<strong>معيار ثانوي:</strong> ظواهر مناعية (عامل روماتويدي إيجابي، عقد Osler، بقع Roth، التهاب كبيبات الكلى بالمركبات المناعية)","chk",{"unitLocale":"ar","displayLocale":"ar"}],["men_micro","<strong>معيار ثانوي:</strong> دليل ميكروبيولوجي لا يستوفي المعيار الرئيسي","chk",{"unitLocale":"ar","displayLocale":"ar"}],["men_img","<strong>معيار ثانوي:</strong> FDG PET/CT غير طبيعي خلال ٣ أشهر من زرع مادة قلبية اصطناعية أو طعم أو جهاز","chk",{"unitLocale":"ar","displayLocale":"ar"}],["men_exame","<strong>معيار ثانوي:</strong> نفخة قلس جديدة بالفحص السريري إذا لم يتوفر الإيكو","chk",{"unitLocale":"ar","displayLocale":"ar"}],["rej_alt","<strong>استبعاد:</strong> تشخيص بديل مؤكد يفسر الحالة","chk",{"unitLocale":"ar","displayLocale":"ar"}],["rej_res","<strong>استبعاد:</strong> لا نكس بعد علاج بالمضادات الحيوية لمدة أقل من ٤ أيام","chk",{"unitLocale":"ar","displayLocale":"ar"}],["rej_pato","<strong>استبعاد:</strong> لا دليل مرضي في الجراحة أو تشريح الجثة، مع مضادات حيوية لأقل من ٤ أيام","chk",{"unitLocale":"ar","displayLocale":"ar"}]],"formula":"<ul><li><strong>مؤكد:</strong> معيار مرضي, <em>أو</em> ٢ كبرى, <em>أو</em> ١ كبرى + ٣ صغرى, <em>أو</em> ٥ صغرى.</li><li><strong>محتمل:</strong> ١ كبرى + ١ صغرى, <em>أو</em> ٣ صغرى.</li><li><strong>مستبعد:</strong> تشخيص بديل مؤكّد، زوال دون نكس مع أقل من ٤ أيام من المضادات، غياب دليل مرضي بالجراحة/التشريح مع أقل من ٤ أيام من المضادات، <em>أو</em> لا يستوفي معايير المحتمل.</li></ul><p><strong>عدّ المعيار الرئيسي الجراحي:</strong> يضيف معيارًا رئيسيًا واحدًا فقط إذا كان محددًا ولم يُحدَّد معيار رئيسي بالتصوير أو المعيار المرضي. يجب التحقق من التأكيد اللاحق المبين في الجدول ٢؛ فالمعيار الرئيسي الميكروبيولوجي في الدم لا يمثل تلقائيًا تأكيدًا لاحقًا في النسيج.</p>","sources":[["Fowler VG et al. The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis: Updating the Modified Duke Criteria. Clin Infect Dis, 2023.","https://doi.org/10.1093/cid/ciad271"],["Li JS et al. Proposed modifications to the Duke criteria for the diagnosis of infective endocarditis. Clin Infect Dis, 2000.","https://doi.org/10.1086/313753"]],"methodVersion":"Duke-ISCVID 2023: تركيبات محددة من الجدول ١؛ المعيار الرئيسي الجراحي مشروط وفق الجدول ٢، I.C، بغياب معيار رئيسي بالتصوير وغياب تأكيد لاحق؛ لا تكافؤ تلقائي مع Duke 2000","methodVersionLocale":"ar","limits":"تعتمد معايير Duke-ISCVID 2023 على تعريفات محددة لعلم الأحياء الدقيقة والتصوير والفحص أثناء الجراحة والحالات المهيئة. لا تُصنّف بعض الكائنات الدقيقة بأنها نمطية إلا عند وجود مادة تعويضية داخل القلب. وتغيّر نسخة 2023 أيضًا متطلبات الزرع مقارنة بالنسخة السابقة؛ لذلك لا تعيد الأعداد وحدها، دون هذه التعريفات، تطبيق النظام الكامل. يقصر الجدول ٢، القسم I.C، المعيار الرئيسي الجراحي على غياب معيار رئيسي بالتصوير وغياب تأكيد نسيجي أو ميكروبيولوجي لاحق. في هذه الواجهة، يمنع تحديد المعيار المرضي إضافة المعيار الرئيسي الجراحي إلى العدد؛ ويظل المعيار الرئيسي الميكروبيولوجي في الدم منفصلًا. يجب على من يملأ النموذج التحقق من التأكيد اللاحق وتعريفات المصدر: فالحقول المنطقية لا تسجل التسلسل الزمني كاملًا ولا كيفية إثبات النتائج. يصحح هذا التحقق هذا العدّ وتركيباته المحددة فقط؛ ولا يثبت صحة التشخيص أو الأداء السريري أو العلاج أو المنهج الكامل.","limitsLocale":"ar","resultLabels":{"Duke-ISCVID 2023":"Duke-ISCVID 2023","Critérios de Duke-ISCVID 2023":"معايير Duke-ISCVID 2023"},"resultUnits":{},"resultValues":{"Definida":"مؤكدة","Possível":"ممكنة","Rejeitada":"مستبعدة"}},"shared":{"select":"اختر","yes":"نعم","no":"لا","optional":"اختياري","numeric":"قيمة رقمية","range":"النطاق","calculate":"احسب","calculating":"جارٍ الحساب…","clear":"مسح","heading":"حساب بشفافية","intro":"تحقق من الفئة السكانية والوحدات والإصدار. تعرض النتيجة المعادلة أو التصنيف دون اتخاذ قرار علاجي تلقائي.","restricted":"السجل متاح للاطلاع","restrictedNote":"الحساب معلّق في هذا الإصدار. يظل السجل والمراجعة المعلّقة والمصادر متاحة للعامة.","resultNote":"نتيجة المعادلة أو التصنيف. يعتمد التفسير والتصرف ومدى الانطباق على التقييم المهني والمصدر المحدد.","invalid":"تعذر الحساب بهذه القيم. تحقق من شروط الاستخدام.","unavailable":"خدمة الحساب غير متاحة. حاول مرة أخرى.","connection":"تعذر الاتصال بخدمة الحساب. تحقق من الاتصال وحاول مرة أخرى.","check":"تحقق من القيم المدخلة.","fleischner":"قبل الحساب: مرجع للعقيدات الرئوية المكتشفة عرضًا. لا تنطبق التوصيات على من هم دون 35 عامًا، أو فحص سرطان الرئة، أو كبت المناعة، أو وجود سرطان أولي معروف.","incompleteAssessment":"لا يمكن حساب المجموع دون تقييم مكتمل."},"ui":{"brand":"ELUCENIA · شيفرة التكامل","clinical":"لم تُجرَ مراجعة سريرية مستقلة.","conditions":"الشروط والمصادر والأذونات","record":"السجل والمراجع","code":"شيفرة JavaScript","cases":"حالات مرجعية","language":"اللغة","formula":"المعادلة الموثقة","edition":"إصدار الطريقة","limits":"الحدود والفئة السكانية","references":"المراجع"}},"zh":{"tool":{"id":"criterios-de-duke","title":"Duke-ISCVID 2023 标准","titleLocale":"zh","summary":"感染性心内膜炎诊断","lead":"结合病理、大标准及小标准，将疑似感染性心内膜炎分为确定、可能或排除。","fields":[["pato","<strong>病理标准：</strong>赘生物、心脏组织、假体或栓子中检出微生物（培养、组织学或 PCR），或组织学显示活动性心内膜炎","chk",{"unitLocale":"zh","displayLocale":"zh"}],["maior_micro","<strong>微生物学主要标准：</strong>典型病原体在 ≥ 2 次独立血培养中检出，偶发病原体在 ≥ 3 次检出；血液 <em>Coxiella</em>、<em>Bartonella</em> 或 <em>T. whipplei</em> PCR 阳性；或特异性血清学（<em>C. burnetii</em> I 相 IgG > 1:800；<em>Bartonella</em> IgG ≥ 1:800）","chk",{"unitLocale":"zh","displayLocale":"zh"}],["maior_img","<strong>影像学主要标准：</strong>心脏超声/CT 显示赘生物、穿孔、动脉瘤、脓肿、假性动脉瘤或瘘；新出现的显著瓣膜反流；新出现的假体裂开；或瓣膜/电极的 FDG PET/CT 异常","chk",{"unitLocale":"zh","displayLocale":"zh"}],["maior_cir","<strong>外科主要标准：</strong>心脏手术中直接检查所证实的心内膜炎，仅在不存在影像学主要标准且无后续组织学或微生物学确认时计入","chk",{"unitLocale":"zh","displayLocale":"zh"}],["men_pred","<strong>次要标准：</strong>易感因素（既往心内膜炎、人工瓣膜、瓣膜修复、先天性心脏病、瓣膜反流或狭窄、心内装置、肥厚型心肌病、注射毒品）","chk",{"unitLocale":"zh","displayLocale":"zh"}],["men_febre","<strong>次要标准：</strong>发热 > 38.0 °C","chk",{"unitLocale":"zh","displayLocale":"zh"}],["men_vasc","<strong>次要标准：</strong>血管现象（动脉栓塞、脓毒性肺梗死、脑或脾脓肿、感染性动脉瘤、颅内或结膜出血、Janeway 损害、化脓性紫癜）","chk",{"unitLocale":"zh","displayLocale":"zh"}],["men_imuno","<strong>次要标准：</strong>免疫现象（类风湿因子阳性、Osler 结节、Roth 斑、免疫复合物性肾小球肾炎）","chk",{"unitLocale":"zh","displayLocale":"zh"}],["men_micro","<strong>次要标准：</strong>未满足主要标准的微生物学证据","chk",{"unitLocale":"zh","displayLocale":"zh"}],["men_img","<strong>次要标准：</strong>假体、移植物或装置植入后 3 个月内 FDG PET/CT 异常","chk",{"unitLocale":"zh","displayLocale":"zh"}],["men_exame","<strong>次要标准：</strong>超声不可用时体检发现新出现的反流性杂音","chk",{"unitLocale":"zh","displayLocale":"zh"}],["rej_alt","<strong>排除：</strong>明确的其他诊断能够解释病情","chk",{"unitLocale":"zh","displayLocale":"zh"}],["rej_res","<strong>排除：</strong>抗生素治疗不足 4 天后未复发","chk",{"unitLocale":"zh","displayLocale":"zh"}],["rej_pato","<strong>排除：</strong>抗生素治疗不足 4 天，手术或尸检无病理证据","chk",{"unitLocale":"zh","displayLocale":"zh"}]],"formula":"<ul><li><strong>确定：</strong> 病理标准, <em>或</em> 2项大标准, <em>或</em> 1项大标准+3项小标准, <em>或</em> 5项小标准.</li><li><strong>可能：</strong> 1项大标准+1项小标准, <em>或</em> 3项小标准.</li><li><strong>排除：</strong> 明确替代诊断；抗生素使用不足4天即消退且无复发；使用抗生素不足4天时手术/尸检无病理证据； <em>或</em> 不符合可能病例标准。</li></ul><p><strong>外科主要标准的计数：</strong>仅在已勾选该项、且未勾选影像学主要标准或病理学标准时增加一个主要标准。须核实表2规定的后续确认；血液微生物学主要标准并不自动等同于后续的组织确认。</p>","sources":[["Fowler VG et al. The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis: Updating the Modified Duke Criteria. Clin Infect Dis, 2023.","https://doi.org/10.1093/cid/ciad271"],["Li JS et al. Proposed modifications to the Duke criteria for the diagnosis of infective endocarditis. Clin Infect Dis, 2000.","https://doi.org/10.1086/313753"]],"methodVersion":"Duke-ISCVID 2023：表1中的选定组合；按表2的I.C节，外科主要标准须满足无影像学主要标准且无后续确认的条件；不自动等同于Duke 2000","methodVersionLocale":"zh","limits":"Duke-ISCVID 2023标准依赖微生物学、影像、术中观察和易感状况的特定定义。某些微生物只有在存在心内假体时才被归为典型病原体。2023版还修改了上一版的培养要求；缺少这些定义时，单纯计数不能重现完整系统。 表2的I.C节规定，外科主要标准仅适用于不存在影像学主要标准且无后续组织学或微生物学确认的情况。在本界面中，勾选病理学标准后不再额外计入外科主要标准；血液微生物学主要标准单独处理。填写者须核实后续确认及来源定义：布尔字段不能记录完整时间顺序，也不能记录各项发现如何获得。本次核对仅修正该计数及已选择的组合，不验证诊断、临床性能、治疗或完整方法。","limitsLocale":"zh","resultLabels":{"Duke-ISCVID 2023":"Duke-ISCVID 2023","Critérios de Duke-ISCVID 2023":"Duke-ISCVID 2023 标准"},"resultUnits":{},"resultValues":{"Definida":"确定","Possível":"可能","Rejeitada":"排除"}},"shared":{"select":"请选择","yes":"是","no":"否","optional":"选填","numeric":"数值","range":"范围","calculate":"计算","calculating":"计算中…","clear":"清除","heading":"透明计算","intro":"请核对适用人群、单位和版本。结果展示公式或分类，不自动作出治疗决定。","restricted":"可查阅工具记录","restrictedNote":"本版本暂停计算。清单、待审事项和来源仍公开。","resultNote":"公式或分类结果。解释、处理及适用性须结合专业评估和所选来源。","invalid":"无法使用这些数值计算。请核对使用条件。","unavailable":"计算服务暂不可用。请重试。","connection":"无法连接计算服务。请检查网络后重试。","check":"请检查输入值。","fleischner":"计算前：此参考适用于偶然发现的肺结节。建议不适用于35岁以下人群、肺癌筛查、免疫抑制或已知原发性癌症患者。","incompleteAssessment":"未完成评估，无法计算总分。"},"ui":{"brand":"ELUCENIA · 集成代码","clinical":"尚未开展独立临床审查。","conditions":"条件、来源与许可","record":"记录与参考文献","code":"JavaScript代码","cases":"参考案例","language":"语言","formula":"已记录的公式","edition":"方法版本","limits":"限制与适用人群","references":"参考文献"}},"ja":{"tool":{"id":"criterios-de-duke","title":"Duke-ISCVID 2023基準","titleLocale":"ja","summary":"感染性心内膜炎の診断","lead":"病理・大・小基準を組み合わせ、感染性心内膜炎の疑いを確定・可能・否定に分類します。","fields":[["pato","<strong>病理基準：</strong>疣贅、心組織、人工物または塞栓内の微生物（培養・組織・PCR）、または組織学的な活動性心内膜炎","chk",{"unitLocale":"ja","displayLocale":"ja"}],["maior_micro","<strong>微生物学的大基準：</strong>典型病原体が ≥ 2回の別個の血液培養、まれな病原体が ≥ 3回で検出；血液中の<em>Coxiella</em>、<em>Bartonella</em>または<em>T. whipplei</em> PCR陽性；または特異的血清反応（<em>C. burnetii</em>のI相IgG > 1:800、<em>Bartonella</em> IgG ≥ 1:800）","chk",{"unitLocale":"ja","displayLocale":"ja"}],["maior_img","<strong>画像的大基準：</strong>心エコー・心臓CTで疣贅、穿孔、動脈瘤、膿瘍、仮性動脈瘤または瘻孔；新規の有意な弁逆流；新規の人工物離開；または弁・電極のFDG PET/CT異常","chk",{"unitLocale":"ja","displayLocale":"ja"}],["maior_cir","<strong>外科的大基準：</strong>心臓手術中の直接観察で確認された心内膜炎。ただし、画像の大基準がなく、その後の組織学的または微生物学的確認もない場合に限る","chk",{"unitLocale":"ja","displayLocale":"ja"}],["men_pred","<strong>小基準：</strong>素因（心内膜炎の既往、人工弁、弁修復、先天性心疾患、弁逆流・狭窄、心内デバイス、肥大型心筋症、注射薬物使用）","chk",{"unitLocale":"ja","displayLocale":"ja"}],["men_febre","<strong>小基準：</strong>発熱 > 38.0 °C","chk",{"unitLocale":"ja","displayLocale":"ja"}],["men_vasc","<strong>小基準：</strong>血管現象（動脈塞栓、敗血症性肺梗塞、脳・脾膿瘍、感染性動脈瘤、頭蓋内・結膜出血、Janeway病変、化膿性紫斑）","chk",{"unitLocale":"ja","displayLocale":"ja"}],["men_imuno","<strong>小基準：</strong>免疫現象（リウマトイド因子陽性、Osler結節、Roth斑、免疫複合体性糸球体腎炎）","chk",{"unitLocale":"ja","displayLocale":"ja"}],["men_micro","<strong>小基準：</strong>大基準を満たさない微生物学的証拠","chk",{"unitLocale":"ja","displayLocale":"ja"}],["men_img","<strong>小基準：</strong>人工物・グラフト・デバイス植込み後3か月以内のFDG PET/CT異常","chk",{"unitLocale":"ja","displayLocale":"ja"}],["men_exame","<strong>小基準：</strong>心エコーを利用できない場合、身体診察で新たな逆流性雑音","chk",{"unitLocale":"ja","displayLocale":"ja"}],["rej_alt","<strong>否定：</strong>病像を説明する確実な代替診断","chk",{"unitLocale":"ja","displayLocale":"ja"}],["rej_res","<strong>否定：</strong>4日未満の抗菌薬治療後に再発なし","chk",{"unitLocale":"ja","displayLocale":"ja"}],["rej_pato","<strong>否定：</strong>抗菌薬治療が4日未満で、手術・剖検に病理所見なし","chk",{"unitLocale":"ja","displayLocale":"ja"}]],"formula":"<ul><li><strong>確定：</strong> 病理基準, <em>または</em> 大基準2項目, <em>または</em> 大基準1+小基準3, <em>または</em> 小基準5項目.</li><li><strong>可能：</strong> 大基準1+小基準1, <em>または</em> 小基準3項目.</li><li><strong>否定：</strong> 確実な別診断、抗菌薬4日未満で消退し再発なし、抗菌薬4日未満での手術・剖検で病理学的証拠なし、 <em>または</em> 可能の基準を満たさない。</li></ul><p><strong>外科的大基準の数え方：</strong>この項目が選択され、画像の大基準も病理学的基準も選択されていない場合にのみ、大基準を一つ加える。表2に定められたその後の確認を確かめる必要がある。血液の微生物学的大基準は、その後の組織での確認を自動的に意味するものではない。</p>","sources":[["Fowler VG et al. The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis: Updating the Modified Duke Criteria. Clin Infect Dis, 2023.","https://doi.org/10.1093/cid/ciad271"],["Li JS et al. Proposed modifications to the Duke criteria for the diagnosis of infective endocarditis. Clin Infect Dis, 2000.","https://doi.org/10.1086/313753"]],"methodVersion":"Duke-ISCVID 2023：表1の選択済みの組合せ。外科的大基準は表2のI.C節に従い、画像の大基準がなく、その後の確認もない場合に限る。Duke 2000と自動的に同等とはしない","methodVersionLocale":"ja","limits":"Duke-ISCVID 2023の基準は、微生物学、画像、術中の観察、素因となる状態の具体的な定義に依存します。一部の微生物は、心内の人工物がある場合にのみ典型的な病原体と分類されます。2023年版では、前版の培養に関する要件も変更されています。これらの定義なしに数だけを数えても、システム全体を再現することにはなりません。 表2のI.C節では、外科的大基準は画像の大基準がなく、その後の組織学的または微生物学的確認もない場合に限られる。この画面では、病理学的基準を選択すると、外科的大基準を追加して数えない。血液の微生物学的大基準は別に扱う。入力者はその後の確認と出典の定義を確かめる必要がある。真偽値の項目は、全ての時系列や所見の取得過程を記録するものではない。この照合で修正するのは当該の数え方と選択済みの組合せのみであり、診断、臨床性能、治療、手法全体を妥当と認めるものではない。","limitsLocale":"ja","resultLabels":{"Duke-ISCVID 2023":"Duke-ISCVID 2023","Critérios de Duke-ISCVID 2023":"Duke-ISCVID 2023基準"},"resultUnits":{},"resultValues":{"Definida":"確定","Possível":"可能性あり","Rejeitada":"否定"}},"shared":{"select":"選択","yes":"はい","no":"いいえ","optional":"任意","numeric":"数値","range":"範囲","calculate":"計算","calculating":"計算中…","clear":"クリア","heading":"根拠を明示して計算","intro":"対象集団、単位、版を確認してください。結果は式または分類を示すもので、治療方針を自動決定しません。","restricted":"記録を参照できます","restrictedNote":"この版では計算を停止しています。目録、未完了の審査、出典は公開されています。","resultNote":"式または分類の結果です。解釈、対応、適用可能性は専門家による評価と選択した出典に依存します。","invalid":"この値では計算できません。使用条件を確認してください。","unavailable":"計算サービスを利用できません。再試行してください。","connection":"計算サービスに接続できません。接続を確認して再試行してください。","check":"入力値を確認してください。","fleischner":"計算前：偶発的に発見された肺結節に関する参考です。35歳未満、肺がん検診、免疫抑制、既知の原発がんには推奨を適用できません。","incompleteAssessment":"評価が完了していないため合計を計算できません。"},"ui":{"brand":"ELUCENIA · 連携コード","clinical":"独立した臨床レビューは実施されていません。","conditions":"条件・出典・許諾","record":"記録・参考文献","code":"JavaScriptコード","cases":"参照ケース","language":"言語","formula":"記載された計算式","edition":"方法の版","limits":"限界・対象集団","references":"参考文献"}},"hi":{"tool":{"id":"criterios-de-duke","title":"Duke-ISCVID 2023 मानदंड","titleLocale":"hi","summary":"संक्रामक एंडोकार्डाइटिस का निदान","lead":"पैथोलॉजिकल, प्रमुख और गौण मानदंड जोड़कर संदिग्ध एंडोकार्डाइटिस को निश्चित, संभावित या निरस्त वर्गीकृत करता है।","fields":[["pato","<strong>पैथोलॉजिकल मानदंड:</strong> वेजिटेशन, हृदय ऊतक, कृत्रिम सामग्री या एम्बोलस में सूक्ष्मजीव (कल्चर, हिस्टोलॉजी या PCR), अथवा हिस्टोलॉजी में सक्रिय एंडोकार्डाइटिस","chk",{"unitLocale":"hi","displayLocale":"hi"}],["maior_micro","<strong>प्रमुख माइक्रोबायोलॉजिकल मानदंड:</strong> विशिष्ट रोगजनक ≥ 2 अलग रक्त कल्चर में, कभी-कभी मिलने वाला रोगजनक ≥ 3 में; रक्त में <em>Coxiella</em>, <em>Bartonella</em> या <em>T. whipplei</em> का PCR पॉज़िटिव; अथवा विशिष्ट सीरोलॉजी (<em>C. burnetii</em> फ़ेज़ I IgG > 1:800; <em>Bartonella</em> IgG ≥ 1:800)","chk",{"unitLocale":"hi","displayLocale":"hi"}],["maior_img","<strong>प्रमुख इमेजिंग मानदंड:</strong> कार्डियक इको/CT पर वेजिटेशन, परफ़ोरेशन, एन्यूरिज़्म, ऐब्सेस, स्यूडोएन्यूरिज़्म या फ़िस्टुला; नया महत्वपूर्ण वाल्व रिगर्जिटेशन; कृत्रिम सामग्री का नया डिहिसेन्स; या वाल्व/इलेक्ट्रोड पर असामान्य FDG PET/CT","chk",{"unitLocale":"hi","displayLocale":"hi"}],["maior_cir","<strong>प्रमुख शल्य-मानदंड:</strong> हृदय की शल्यक्रिया के दौरान प्रत्यक्ष निरीक्षण से दर्ज एंडोकार्डाइटिस, केवल तब जब प्रमुख इमेजिंग मानदंड और बाद की ऊतकवैज्ञानिक या सूक्ष्मजीववैज्ञानिक पुष्टि दोनों अनुपस्थित हों","chk",{"unitLocale":"hi","displayLocale":"hi"}],["men_pred","<strong>गौण मानदंड:</strong> पूर्वप्रवृत्ति (पूर्व एंडोकार्डाइटिस, कृत्रिम वाल्व, वाल्व रिपेयर, जन्मजात हृदय रोग, वाल्व रिगर्जिटेशन/स्टेनोसिस, इंट्राकार्डियक डिवाइस, हाइपरट्रॉफ़िक कार्डियोमायोपैथी, इंजेक्शन से नशीले पदार्थों का उपयोग)","chk",{"unitLocale":"hi","displayLocale":"hi"}],["men_febre","<strong>गौण मानदंड:</strong> बुखार > 38.0 °C","chk",{"unitLocale":"hi","displayLocale":"hi"}],["men_vasc","<strong>गौण मानदंड:</strong> संवहनी घटनाएँ (धमनी एम्बोलिज़्म, सेप्टिक पल्मोनरी इन्फ़ार्क्ट, मस्तिष्क/प्लीहा ऐब्सेस, संक्रमित एन्यूरिज़्म, इंट्राक्रैनियल/कंजंक्टाइवल रक्तस्राव, Janeway घाव, पूययुक्त पुरपुरा)","chk",{"unitLocale":"hi","displayLocale":"hi"}],["men_imuno","<strong>गौण मानदंड:</strong> प्रतिरक्षात्मक घटनाएँ (रूमेटॉइड फ़ैक्टर पॉज़िटिव, Osler नोड्यूल, Roth धब्बे, इम्यून कॉम्प्लेक्स ग्लोमेरुलोनेफ़्राइटिस)","chk",{"unitLocale":"hi","displayLocale":"hi"}],["men_micro","<strong>गौण मानदंड:</strong> माइक्रोबायोलॉजिकल प्रमाण जो प्रमुख मानदंड पूरा नहीं करता","chk",{"unitLocale":"hi","displayLocale":"hi"}],["men_img","<strong>गौण मानदंड:</strong> कृत्रिम सामग्री, ग्राफ़्ट या डिवाइस लगाने के 3 महीनों के भीतर असामान्य FDG PET/CT","chk",{"unitLocale":"hi","displayLocale":"hi"}],["men_exame","<strong>गौण मानदंड:</strong> इकोकार्डियोग्राम उपलब्ध न होने पर शारीरिक परीक्षण में नया रिगर्जिटेशन मर्मर","chk",{"unitLocale":"hi","displayLocale":"hi"}],["rej_alt","<strong>अस्वीकृति:</strong> स्थिति को समझाने वाला निश्चित वैकल्पिक निदान","chk",{"unitLocale":"hi","displayLocale":"hi"}],["rej_res","<strong>अस्वीकृति:</strong> 4 दिनों से कम एंटीबायोटिक उपचार के बाद पुनरावृत्ति नहीं","chk",{"unitLocale":"hi","displayLocale":"hi"}],["rej_pato","<strong>अस्वीकृति:</strong> 4 दिनों से कम एंटीबायोटिक उपचार के साथ सर्जरी या शव-परीक्षण में पैथोलॉजिकल प्रमाण नहीं","chk",{"unitLocale":"hi","displayLocale":"hi"}]],"formula":"<ul><li><strong>निश्चित:</strong> पैथोलॉजिकल मानदंड, <em>या</em> 2 प्रमुख, <em>या</em> 1 प्रमुख + 3 गौण, <em>या</em> 5 गौण.</li><li><strong>संभावित:</strong> 1 प्रमुख + 1 गौण, <em>या</em> 3 गौण.</li><li><strong>निरस्त:</strong> निश्चित वैकल्पिक निदान, 4 दिनों से कम एंटीबायोटिक पर बिना पुनरावृत्ति समाधान, 4 दिनों से कम एंटीबायोटिक के बाद शल्यक्रिया/शवपरीक्षण में पैथोलॉजिकल प्रमाण नहीं, <em>या</em> संभावित के मानदंड पूरे नहीं होते।</li></ul><p><strong>प्रमुख शल्य-मानदंड की गिनती:</strong> एक प्रमुख मानदंड केवल तभी जोड़ता है जब यह चुना गया हो और न प्रमुख इमेजिंग मानदंड चुना गया हो, न पैथोलॉजिकल मानदंड। तालिका 2 में वर्णित बाद की पुष्टि की जाँच आवश्यक है; रक्त का प्रमुख सूक्ष्मजीववैज्ञानिक मानदंड अपने-आप ऊतक में बाद की पुष्टि नहीं है।</p>","sources":[["Fowler VG et al. The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis: Updating the Modified Duke Criteria. Clin Infect Dis, 2023.","https://doi.org/10.1093/cid/ciad271"],["Li JS et al. Proposed modifications to the Duke criteria for the diagnosis of infective endocarditis. Clin Infect Dis, 2000.","https://doi.org/10.1086/313753"]],"methodVersion":"Duke-ISCVID 2023: तालिका 1 के चुने गए संयोजन; तालिका 2, I.C के अनुसार प्रमुख शल्य-मानदंड के लिए प्रमुख इमेजिंग मानदंड और बाद की पुष्टि दोनों अनुपस्थित होने चाहिए; Duke 2000 से अपने-आप समानता नहीं","methodVersionLocale":"hi","limits":"Duke-ISCVID 2023 मानदंड सूक्ष्मजीवविज्ञान, इमेजिंग, शल्यक्रिया के दौरान निरीक्षण और पूर्वप्रवणता वाली स्थितियों की विशिष्ट परिभाषाओं पर निर्भर हैं। कुछ सूक्ष्मजीव केवल हृदय के भीतर कृत्रिम उपकरण मौजूद होने पर विशिष्ट रोगजनक माने जाते हैं। 2023 संस्करण पिछले संस्करण की कल्चर-संबंधी आवश्यकताओं को भी बदलता है; इन परिभाषाओं के बिना केवल गिनती पूरे तंत्र को पुनः लागू नहीं करती। तालिका 2, खंड I.C, प्रमुख शल्य-मानदंड को तभी मानता है जब प्रमुख इमेजिंग मानदंड और बाद की ऊतकवैज्ञानिक या सूक्ष्मजीववैज्ञानिक पुष्टि दोनों अनुपस्थित हों। इस इंटरफ़ेस में पैथोलॉजिकल मानदंड चुनने पर प्रमुख शल्य-मानदंड की अतिरिक्त गिनती नहीं होती; रक्त का प्रमुख सूक्ष्मजीववैज्ञानिक मानदंड अलग रहता है। फ़ॉर्म भरने वाले को बाद की पुष्टि और स्रोत की परिभाषाएँ जाँचनी चाहिए: बूलियन फ़ील्ड पूरी समय-रेखा या निष्कर्ष कैसे प्राप्त हुए, यह दर्ज नहीं करते। यह जाँच केवल इस गिनती और चुने गए संयोजनों को सुधारती है; निदान, नैदानिक प्रदर्शन, उपचार या संपूर्ण विधि को सत्यापित नहीं करती।","limitsLocale":"hi","resultLabels":{"Duke-ISCVID 2023":"Duke-ISCVID 2023","Critérios de Duke-ISCVID 2023":"Duke-ISCVID 2023 मानदंड"},"resultUnits":{},"resultValues":{"Definida":"निश्चित","Possível":"संभावित","Rejeitada":"अस्वीकृत"}},"shared":{"select":"चुनें","yes":"हाँ","no":"नहीं","optional":"वैकल्पिक","numeric":"संख्यात्मक मान","range":"सीमा","calculate":"गणना करें","calculating":"गणना जारी है…","clear":"साफ़ करें","heading":"पारदर्शिता के साथ गणना","intro":"जनसमूह, इकाइयाँ और संस्करण जाँचें। परिणाम सूत्र या वर्गीकरण दिखाता है; यह स्वतः उपचार संबंधी निर्णय नहीं देता।","restricted":"रिकॉर्ड देखने के लिए उपलब्ध है","restrictedNote":"इस संस्करण में गणना रुकी हुई है। सूची, लंबित समीक्षा और स्रोत सार्वजनिक हैं।","resultNote":"सूत्र या वर्गीकरण का परिणाम। व्याख्या, कार्यवाही और उपयुक्तता पेशेवर मूल्यांकन और चुने गए स्रोत पर निर्भर है।","invalid":"इन मानों से गणना नहीं हो सकी। उपयोग की शर्तें जाँचें।","unavailable":"गणना सेवा उपलब्ध नहीं है। फिर प्रयास करें।","connection":"गणना सेवा से संपर्क नहीं हो सका। कनेक्शन जाँचकर फिर प्रयास करें।","check":"दर्ज मान जाँचें।","fleischner":"गणना से पहले: आकस्मिक रूप से पाए गए फेफड़ों के नोड्यूल के लिए संदर्भ। सिफ़ारिशें 35 वर्ष से कम आयु, फेफड़ों के कैंसर की स्क्रीनिंग, प्रतिरक्षा दमन या ज्ञात प्राथमिक कैंसर पर लागू नहीं होतीं।","incompleteAssessment":"पूर्ण मूल्यांकन के बिना कुल स्कोर नहीं निकाला जा सकता।"},"ui":{"brand":"ELUCENIA · एकीकरण कोड","clinical":"स्वतंत्र नैदानिक समीक्षा नहीं की गई है।","conditions":"शर्तें, स्रोत और अनुमतियाँ","record":"रिकॉर्ड और संदर्भ","code":"JavaScript कोड","cases":"संदर्भ मामले","language":"भाषा","formula":"दस्तावेज़ित सूत्र","edition":"विधि का संस्करण","limits":"सीमाएँ और जनसमूह","references":"संदर्भ"}}}};
